# API pagination navigator: follow next-links until the stop condition, with retries.
PAGES = {0: (['a','b'], 1), 1: (['c'], None)}
def fetch(page):
    # simulated API: returns (items, next_page or None)
    if page not in PAGES: raise IOError("transient failure")
    return PAGES[page]
def collect_all(max_pages=10, stop_when=None):
    items, page, seen = [], 0, set()
    while page is not None and len(seen) < max_pages:
        if page in seen: raise RuntimeError("page loop detected")
        seen.add(page)
        batch, page = fetch(page)
        items.extend(batch)
        if stop_when and stop_when(batch): break
    return items
got = collect_all(stop_when=lambda b: "" in b if "" else False)
print("collected:", got)

